import { useCallback, useMemo } from 'react';

import { useCommercialSelectOptions } from 'components/Filter/hooks/useCommercialSelectOptions';
import { FieldProps } from 'components/Filter/types';
import { isCommercialResultsFilterPage } from 'components/Filter/utils/commercialSelectOptions';
import {
  resolveFilterClearTargetOption,
  shouldShowFilterSelectClearIndicator,
} from 'components/Filter/utils/filterClearableSelectPolicy';
import { Select } from 'components/Form';
import { FilterDataAccessor } from 'domain/Filter/FilterDataAccessor';
import { PerformanceToolFilterDataTransformer } from 'domain/Filter/FilterDataTransformer';
import { useGoogleAnalytics, usePageFilterData } from 'hooks';
import { useFilterRules } from 'hooks/useFilters/core/useFilterRules';
import { Option } from 'models/Filters';

export const SubBrandsField = ({
  dataTestId,
  fieldKey,
  pageName,
  onValueChange,
  getCurrentValue,
}: FieldProps) => {
  const trackGA = useGoogleAnalytics();
  const { dataFilters, formDataFilters, formPresetRawData, defaults } =
    usePageFilterData(pageName);
  const { getFieldConfig } = useFilterRules();

  const kpiValue = getCurrentValue('kpis');
  const countryValue = getCurrentValue('country');
  const zoneValue = getCurrentValue('zone');
  const growthLeverValue = getCurrentValue('growth_levers');
  const brandClassValue = getCurrentValue('brand_filter_groupings');
  const brandValue = getCurrentValue('brands');
  const portfolioValue = getCurrentValue('portfolios');
  const beerPriceSegmentValue = getCurrentValue('beer_price_segment');

  const fieldConfig = useMemo(
    () =>
      getFieldConfig('sub_brands', {
        kpi: kpiValue,
        growthLever: growthLeverValue,
        country: countryValue,
        zone: zoneValue,
        brandClass: brandClassValue,
        brand: brandValue,
        portfolio: portfolioValue,
        beerPriceSegment: beerPriceSegmentValue,
      }),
    [
      getFieldConfig,
      kpiValue,
      growthLeverValue,
      countryValue,
      zoneValue,
      brandClassValue,
      brandValue,
      portfolioValue,
      beerPriceSegmentValue,
    ],
  );

  const accessorRawOptions: Option[] = useMemo(() => {
    const accessor = FilterDataAccessor.getInstance();
    const primary = isCommercialResultsFilterPage(pageName)
      ? formDataFilters
      : dataFilters;
    const secondary = isCommercialResultsFilterPage(pageName)
      ? dataFilters
      : formDataFilters;

    const primaryOptions = accessor.getOptions(fieldKey, primary, {
      country: countryValue,
      brands: brandValue,
    }) as Option[];
    if (primaryOptions.length > 0) return primaryOptions;
    return accessor.getOptions(fieldKey, secondary, {
      country: countryValue,
      brands: brandValue,
    }) as Option[];
  }, [
    fieldKey,
    pageName,
    dataFilters,
    formDataFilters,
    countryValue,
    brandValue,
  ]);

  const currentValue = getCurrentValue(fieldKey);

  const {
    rawOptions,
    selectableOptions,
    isCommercialPage,
    commercialDisplayValue,
  } = useCommercialSelectOptions({
    pageName,
    rawOptions: accessorRawOptions,
    formValue: currentValue,
    defaultValue: defaults?.[fieldKey],
  });

  const displayValue = isCommercialPage ? commercialDisplayValue : currentValue;

  const subBrandToBrandMap = useMemo(
    () =>
      PerformanceToolFilterDataTransformer.buildSubBrandToBrandMap(
        formPresetRawData,
        kpiValue,
        {
          zone: zoneValue,
          country: countryValue,
          growth_levers: growthLeverValue,
        },
      ),
    [formPresetRawData, kpiValue, zoneValue, countryValue, growthLeverValue],
  );

  const handleValueChange = useCallback(
    (option: Option) => {
      if (option?.value === null || option?.value === '') {
        onValueChange(fieldKey, { value: null, label: '' });
        return;
      }
      if (!option?.value) return;

      trackGA({
        event_category: 'Sub Brand Select',
        event_action: 'Select',
        event_label: option?.value as string,
      });

      const selectedSubBrand = option.value as string;
      const correspondingBrand = subBrandToBrandMap[selectedSubBrand];

      // Auto-select parent brand when:
      // 1. Current brand is "All", OR
      // 2. Current brand doesn't match the selected sub-brand's parent
      if (
        correspondingBrand &&
        (brandValue === 'All' || brandValue !== correspondingBrand)
      ) {
        onValueChange('brands', {
          value: correspondingBrand,
          label: correspondingBrand,
        });
      }

      onValueChange(fieldKey, option);
    },
    [trackGA, fieldKey, onValueChange, subBrandToBrandMap, brandValue],
  );

  const clearable = shouldShowFilterSelectClearIndicator(
    pageName,
    fieldKey,
    String(currentValue ?? ''),
    rawOptions,
    defaults,
  );

  return (
    <Select
      dataTestId={dataTestId ? `${dataTestId}-${fieldKey}` : undefined}
      id={`${fieldKey}-select`}
      label={fieldConfig.label}
      value={displayValue}
      options={selectableOptions}
      clearable={clearable}
      onValueChange={(option) => {
        const opt = Array.isArray(option) ? option[0] : option;
        if (opt === '') {
          const target = resolveFilterClearTargetOption(
            fieldKey,
            rawOptions,
            defaults,
          );
          if (target !== undefined) {
            handleValueChange(target);
          }
          return;
        }
        handleValueChange(opt as Option);
      }}
      placeholder={fieldConfig.placeholder || 'Select a sub-brand'}
      disabled={fieldConfig.disabled}
    />
  );
};

export default SubBrandsField;
